import { createStore } from 'vuex';
import { io } from 'socket.io-client';
import axios from 'axios';

let socketInstance = null;

export default createStore({
  state: {
    coinData: {},
    coinList: [],
    isConnected: false,
    lastUpdateTime: null,
    settings: {
      crossEnabled: true,
      intraEnabled: true,
      paribuEnabled: true,
      crossMinProfit: 1000,
      crossMinROI: 0.50,
      crossCooldown: 5,
      intraMinROI: 0,
      intraMinProfit: 100,
      intraCooldown: 5,
      paribuMinROI: 0,
      paribuMinProfit: 50,
      blockedCoins: [],
      topCoins: ['btc', 'bnb', 'eth', 'usdt', 'fet', 'sol', 'ftt', 'xrp', 'pepe', 'shib', 'btt', 'chz'],
      topDealsCount: 10
    },
    isInitialized: false,
    isAuthenticated: false,
    currentUser: null
  },
  mutations: {
    SET_AUTH(state, { isAuthenticated, user }) {
      state.isAuthenticated = isAuthenticated;
      state.currentUser = user || null;
    },
    SET_COIN_DATA(state, data) {
      if (data && typeof data === 'object') {
        state.coinData = data;
        state.coinList = Object.keys(data).filter(k => k !== 'usdt');
        state.lastUpdateTime = Date.now();
        state.isInitialized = true;
      }
    },
    SET_CONNECTED(state, val) {
      state.isConnected = val;
    },
    SET_SETTINGS(state, settings) {
      state.settings = { ...state.settings, ...settings };
    }
  },
  actions: {
    initSocket({ commit, dispatch }) {
      if (socketInstance) return; // Persistent singleton socket across entire SPA lifecycle

      const isDemo = typeof window !== 'undefined' && 
        (window.location.hostname.includes('github.io') || window.location.search.includes('demo=1'));
      if (isDemo) return;

      socketInstance = io();

      socketInstance.on('connect', () => {
        commit('SET_CONNECTED', true);
        console.log('⚡ [Vuex] Global WebSocket connected');
      });

      socketInstance.on('data_update', (data) => {
        if (data && (data.btc || Object.keys(data).length > 5)) {
          commit('SET_COIN_DATA', data);
        }
      });

      socketInstance.on('settings_update', (newSettings) => {
        if (newSettings && typeof newSettings === 'object') {
          console.log('⚙️ [Vuex] Live settings update received');
          commit('SET_SETTINGS', newSettings);
        }
      });

      socketInstance.on('disconnect', () => {
        commit('SET_CONNECTED', false);
        console.log('⚠️ [Vuex] Global WebSocket disconnected');
      });

      dispatch('checkAuth');
      dispatch('fetchSettings');
    },

    async checkAuth({ commit }) {
      try {
        const res = await axios.get('/api/auth/status', { withCredentials: true });
        if (res.data && res.data.authenticated) {
          commit('SET_AUTH', { isAuthenticated: true, user: res.data.user });
          return res.data;
        }
      } catch (e) {}

      // Fallback: check document.cookie directly for as_auth_token
      try {
        const match = document.cookie.match(/as_auth_token=([^;]+)/);
        if (match && match[1]) {
          const base64Url = match[1].split('.')[1];
          const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
          const payload = JSON.parse(window.atob(base64));
          if (payload && payload.role === 'admin' && payload.exp * 1000 > Date.now()) {
            commit('SET_AUTH', { isAuthenticated: true, user: payload });
            return { authenticated: true, user: payload };
          }
        }
      } catch (e) {}

      commit('SET_AUTH', { isAuthenticated: false, user: null });
    },

    async login({ dispatch }, { username, password }) {
      const res = await axios.post('/api/auth/login', { username, password }, { withCredentials: true });
      if (res.data && res.data.success) {
        await dispatch('checkAuth');
        // Reconnect socket to join admin room
        if (socketInstance) {
          socketInstance.disconnect();
          socketInstance.connect();
        }
        return res.data;
      }
      throw new Error(res.data?.error || 'Login failed');
    },

    async logout({ commit }) {
      try {
        await axios.post('/api/auth/logout', {}, { withCredentials: true });
      } catch (e) {}
      commit('SET_AUTH', { isAuthenticated: false, user: null });
      window.location.reload();
    },

    async fetchSettings({ commit }) {
      try {
        const response = await axios.get('/api/settings');
        if (response.data) {
          commit('SET_SETTINGS', response.data);
        }
      } catch (e) {
        // Fallback silently if offline or demo
      }
    }
  },
  getters: {
    coinData: state => state.coinData,
    isConnected: state => state.isConnected,
    isInitialized: state => state.isInitialized,
    usdtRate: state => {
      const d = state.coinData;
      if (d && d['usdt']) {
        if (d['usdt'].binance?.try?.price) return d['usdt'].binance.try.price;
        if (d['usdt'].paribu?.try?.price) return d['usdt'].paribu.try.price;
        if (d['usdt'].BTCTurk?.try?.price) return d['usdt'].BTCTurk.try.price;
      }
      return 36.5;
    }
  }
});
